//
//  drr.hpp
//  AMDRadeonRDNA4
//
//  Variable refresh (DisplayPort Adaptive-Sync, FreeSync) on a pipe, as amdgpu programs it on DCN 4.01: the OTG's
//  V total ranges between a minimum and a maximum, and each flip ends the stretched blank (docs/freesync-plan.md).
//  The register steps are Linux's, generated by tools/gen/pipegen (run.sh drr) into src/drr_linux.inc.
//

#ifndef Drr_hpp
#define Drr_hpp

#include <stddef.h>
#include <stdint.h>

#include "modeset.hpp"

namespace Drr {

enum Kind : uint8_t { kPlain, kVMin, kVMax };   // kVMin/kVMax: the value is the V total - 1

struct Step {
	uint8_t  seg;
	uint16_t dword;
	uint32_t mask, value;
	Kind     kind;
};

enum class Phase : uint8_t {
	On,        // variable between the V totals given (lines)
	Off,       // fixed again
	Trigger,   // after a flip: end the blank now (only while On)
};

// Pipe `pipe`'s steps for `phase` as ModeSet steps (Write, or Update for a part of a register); 0 for a pipe without
// a table or an `out` too small.
size_t build(uint8_t pipe, Phase phase, uint32_t vTotalMin, uint32_t vTotalMax, ModeSet::Step *out, size_t max);

// Whether pipe `pipe` runs variable: set by whoever runs its On or Off steps; its flips then fire the trigger.
void setActive(uint8_t pipe, bool on);
bool active(uint8_t pipe);

// The write that ends pipe `pipe`'s stretched blank, when its refresh is variable: after a flip, and after a cursor move
// (DC's DRR_TRIGGER_ON_FLIP_AND_CURSOR). False when there is nothing to write.
bool trigger(uint8_t pipe, ModeSet::Step &out);

// DPCD: the sink can ignore the MSA timing (DOWN_STREAM_PORT_COUNT, 0x007 bit 6), and is told to (DOWNSPREAD_CTRL,
// 0x107 bit 7), as Linux's enable_stream_features does for a stream with variable refresh.
constexpr uint32_t kDpcdPortCount = 0x007, kDpcdDownspread = 0x107;
constexpr uint8_t  kMsaIgnoreCapable = 0x40, kMsaIgnore = 0x80;

} // namespace Drr

#endif /* Drr_hpp */
